  function updateFilter(key: string, value: string) { const next = new URLSearchParams(params); value ? next.set(key,value) : next.delete(key); setParams(next) }
  return <div className="page-content"><PageHeading eyebrow="GRAND LINE · NEWS COO" title="El mundo" highlight="no se detiene." description="Rumores, reportes y noticias que pueden cambiar el curso de la historia." action={<span className="count-pill"><Globe2 size={15}/> TRANSMISIÓN GLOBAL</span>}/>
    <div className="news-filter-bar"><div className="news-filter-title"><Newspaper size={17}/><span>FILTRO DE TRANSMISIONES</span></div><label><span>Tipo</span><select value={type} onChange={e => updateFilter('type',e.target.value)}><option value="">Todos</option>{['POLITICS','PIRATES','MARINES','ECONOMY','WORLD_EVENT','OTHER'].map(v => <option key={v}>{v}</option>)}</select></label><label><span>Prioridad</span><select value={priority} onChange={e => updateFilter('priority',e.target.value)}><option value="">Todas</option>{['LOW','MEDIUM','HIGH','CRITICAL'].map(v => <option key={v}>{v}</option>)}</select></label><label><span>Estado</span><select value={status} onChange={e => updateFilter('status',e.target.value)}><option value="">Todos</option>{['RUMOR','CONFIRMED','DEBUNKED'].map(v => <option key={v}>{v}</option>)}</select></label></div>
    {error && <div className="inline-error"><span>{error}</span><button className="secondary-btn" onClick={() => { if (items.length && nextCursor) void loadMore(); else setRefreshIndex(v => v+1) }}>Reintentar <ArrowRight size={14}/></button></div>}
    {initial && loading ? <LoadingState text="News Coo está buscando señales…"/> : items.length === 0 && !loading ? <EmptyState title="Silencio en las ondas" detail="No se encontraron noticias con los filtros actuales."/> : <div className="news-layout"><div className="news-feed">{items.map((item,index) => <NewsCard item={item} key={idOf(item) || index}/>) }<div ref={sentinel} className="feed-sentinel" aria-hidden="true"/>{loading && <div className="feed-loading"><span className="spinner dark-spinner"/> Recibiendo nuevas transmisiones…</div>}{!hasMore && !loading && <div className="feed-end"><span/> FIN DE TRANSMISIÓN <span/></div>}</div><aside className="news-aside"><div className="broadcast-card"><div className="broadcast-icon"><Bell size={21}/></div><span className="destination-number">NEWS COO NETWORK</span><h3>El rumor vuela.<br/><em>La verdad permanece.</em></h3><p>Verifica los reportes marcados como rumor para ayudar a la Guild a separar hechos de ficción.</p><div className="broadcast-stat"><span>REPORTES EN TU FEED</span><b>{items.length}</b></div></div><div className="broadcast-tip"><Shield size={18}/><p>Solo los reportes en estado <b>RUMOR</b> pueden confirmarse o desmentirse.</p></div></aside></div>}
  </div>
