  return <Link to={`/news/${encodeURIComponent(idOf(item))}`} className="news-card"><div className={`news-priority priority-${priority}`}/><div className="news-card-content"><div className="news-meta"><span className="news-type">{type}</span><span className={`news-status status-${status.toLowerCase()}`}>{status}</span><span className="news-date">{labelOf(item,'publishedAt','published_at','createdAt','date')}</span></div><h3>{labelOf(item,'title','headline')}</h3><p>{labelOf(item,'summary','excerpt','description')}</p><div className="news-card-bottom"><span>{labelOf(item,'source','origin','author')}</span><span className="read-report">LEER REPORTE <ArrowRight size={14}/></span></div></div><div className="news-card-arrow"><ArrowRight size={17}/></div></Link>
