  const load = useCallback(() => { setLoading(true); setError(''); request<unknown>('/sagas').then(data => { const r=asRecord(data); setItems(asArray(r.items ?? r.content ?? r.sagas ?? data).map(asRecord) as SagaItem[]) }).catch(e=>setError(prettyError(e))).finally(()=>setLoading(false)) },[])
